-- A warehouse is written once, like a branch. A fiscal period is written once; only its lock
-- changes. The app can read number_series and nothing more: the counter moves only through
-- app.next_document_number below.
GRANT SELECT, INSERT ON public.warehouses, public.fiscal_periods TO app_runtime;
--> statement-breakpoint
GRANT UPDATE (locked_at, locked_by) ON public.fiscal_periods TO app_runtime;
