-- A member sees the warehouses of the branches they work in, as with branches themselves; an
-- owner adds them.
CREATE POLICY warehouses_select ON public.warehouses FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (
      (SELECT app.tenant_branch_ids()) IS NULL
      OR branch_id = ANY ((SELECT app.tenant_branch_ids())::uuid[])
    )
  );
--> statement-breakpoint
CREATE POLICY warehouses_insert ON public.warehouses FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND created_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
-- Every member reads the periods: any document needs to know whether its date is open. Only an
-- owner opens a fiscal year, and only an owner locks or unlocks a period, under their own name.
CREATE POLICY fiscal_periods_select ON public.fiscal_periods FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()));
--> statement-breakpoint
CREATE POLICY fiscal_periods_insert ON public.fiscal_periods FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND created_by = (SELECT app.current_user_id())
    AND locked_at IS NULL
  );
--> statement-breakpoint
CREATE POLICY fiscal_periods_update ON public.fiscal_periods FOR UPDATE TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) = 'owner')
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND (locked_by IS NULL OR locked_by = (SELECT app.current_user_id()))
  );
--> statement-breakpoint
-- The counters are for the books: an owner, an accountant or an auditor may look at them.
CREATE POLICY number_series_select ON public.number_series FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor'));
--> statement-breakpoint

-- ── hand-written: the next document number ──────────────────────────────────────────────────────
-- Hands out the next number for a kind of document on a date, such as SI-2627-00001: the kind,
-- the fiscal year the date falls in, and a counter that restarts each fiscal year.
--
-- It must be called inside the transaction that writes the document. The counter's row stays
-- locked until that transaction ends, so two documents written at the same moment wait their
-- turn and get consecutive numbers; if the document fails, the counter goes back with it and no
-- number is lost. It refuses a date no fiscal period covers (SE001) and a locked period (SE002).
CREATE FUNCTION app.next_document_number(p_type text, p_date date) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = ''
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_year_start date;
  v_locked timestamptz;
  v_code text;
  v_number bigint;
BEGIN
  IF v_tenant IS NULL OR app.tenant_role() = 'auditor' THEN
    RAISE EXCEPTION 'not allowed to number a document' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_type IS NULL OR p_type !~ '^[A-Z]{2}$' OR p_date IS NULL THEN
    RAISE EXCEPTION 'a document number needs a document type and a date' USING ERRCODE = 'check_violation';
  END IF;
  SELECT p.year_start, p.locked_at INTO v_year_start, v_locked
    FROM public.fiscal_periods p
    WHERE p.tenant_id = v_tenant AND p.starts_on <= p_date AND p.ends_on >= p_date;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no fiscal period covers %', p_date USING ERRCODE = 'SE001';
  END IF;
  IF v_locked IS NOT NULL THEN
    RAISE EXCEPTION 'the fiscal period of % is locked', p_date USING ERRCODE = 'SE002';
  END IF;
  -- "2627" for a year that starts in July 2026; "2026" for a calendar year.
  v_code := CASE WHEN extract(month FROM v_year_start) = 1
              THEN to_char(v_year_start, 'YYYY')
              ELSE to_char(v_year_start, 'YY') || to_char(v_year_start + interval '1 year', 'YY')
            END;
  INSERT INTO public.number_series (tenant_id, document_type, year_start, year_code, next_number)
    VALUES (v_tenant, p_type, v_year_start, v_code, 2)
    ON CONFLICT (tenant_id, document_type, year_start)
    DO UPDATE SET next_number = public.number_series.next_number + 1, updated_at = now()
    RETURNING next_number - 1 INTO v_number;
  RETURN p_type || '-' || v_code || '-' ||
    CASE WHEN v_number < 100000 THEN lpad(v_number::text, 5, '0') ELSE v_number::text END;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.next_document_number(text, date) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.next_document_number(text, date) TO app_runtime;
